static boolean isPalindrome(String s) {
    LinkedList<Character> deque = new LinkedList<>();
    for (char c : s.toCharArray()) deque.add(c);
    while (deque.size() > 1) {
        if (!deque.pollFirst().equals(deque.pollLast())) return false;
    }
    return true;
}

