class SimpleLRU<T> {
    private LinkedList<T> list = new LinkedList<>();
    private int capacity;

    SimpleLRU(int capacity) { this.capacity = capacity; }

    void access(T element) {
        list.remove(element); // usun jesli istnieje (no-op jesli nie istnieje)
        list.addFirst(element);
        if (list.size() > capacity) list.removeLast();
        System.out.println("Po access(" + element + "): " + list);
    }
}

