static void insertSorted(LinkedList<Integer> list, int value) {
    ListIterator<Integer> lit = list.listIterator();
    while (lit.hasNext()) {
        if (lit.next() > value) {
            lit.previous();
            lit.add(value);
            return;
        }
    }
    lit.add(value);
}

