static LinkedList<Integer> reverseInGroups(LinkedList<Integer> list, int k) {
    LinkedList<Integer> result = new LinkedList<>();
    LinkedList<Integer> copy = new LinkedList<>(list);
    while (!copy.isEmpty()) {
        LinkedList<Integer> group = new LinkedList<>();
        for (int i = 0; i < k && !copy.isEmpty(); i++) group.addFirst(copy.pollFirst());
        result.addAll(group);
    }
    return result;
}

