LinkedList<Integer> sorted = new LinkedList<>();
int[] values = {5, 10, 3, 8, 1};
for (int v : values) {
    ListIterator<Integer> lit = sorted.listIterator();
    boolean inserted = false;
    while (lit.hasNext()) {
        if (lit.next() > v) { lit.previous(); lit.add(v); inserted = true; break; }
    }
    if (!inserted) sorted.add(v);

    int n = sorted.size();
    double median = n % 2 == 0
        ? (sorted.get(n/2 - 1) + sorted.get(n/2)) / 2.0
        : sorted.get(n/2);
    System.out.println("Po dodaniu " + v + ", mediana=" + median);
}

class MinMaxStructure {
    private LinkedList<Integer> sorted = new LinkedList<>();

    void add(int v) {
        ListIterator<Integer> lit = sorted.listIterator();
        while (lit.hasNext()) {
            if (lit.next() > v) { lit.previous(); lit.add(v); return; }
        }
        sorted.addLast(v);
    }

    int min() { return sorted.getFirst(); }
    int max() { return sorted.getLast(); }
}

