System.out.println("Min: " + structure.min() + ", Max: " + structure.max());

record Event(long time, String data) {}

class TimeWindow {
    private LinkedList<Event> events = new LinkedList<>();

    void addEvent(long time, String data) { events.addLast(new Event(time, data)); }

    void evict(long cutoffTime) {
        while (!events.isEmpty() && events.peekFirst().time() < cutoffTime) {
            events.pollFirst();
        }
    }

    int getCount() { return events.size(); }
}

