class MultiLevelQueue<T> {
    private LinkedList<T> high = new LinkedList<>();
    private LinkedList<T> medium = new LinkedList<>();
    private LinkedList<T> low = new LinkedList<>();

    void addHigh(T v) { high.addLast(v); }
    void addMedium(T v) { medium.addLast(v); }
    void addLow(T v) { low.addLast(v); }

    T poll() {
        if (!high.isEmpty()) return high.pollFirst();
        if (!medium.isEmpty()) return medium.pollFirst();
        if (!low.isEmpty()) return low.pollFirst();
        return null;
    }
}

